insert into public.edital_programas (edital_catalog_id, subject_catalog_id, texto, fonte_url, conferido_em)
select e.id, s.id, v.texto, 'https://centrodeselecao.ufg.br/2021/tj-go/sistema/arquivos/anexos/ANEXO_IV_PROGRAMAS_DAS_PROVAS_RETIFICADO_N1.pdf', '2026-08-03'
from (values
  ('tj-go-analista-apoio-administrativo', 'Língua Portuguesa', 'Leitura e análise de textos de diferentes gêneros textuais. Linguagem verbal e não-verbal. Mecanismos de produção de sentidos nos textos: polissemia, ironia, comparação, ambiguidade, citação, inferência, pressuposto. Significados contextuais das expressões linguísticas. Organização do texto: Fatores de textualidade (coesão, coerência, intertextualidade, informatividade, intencionalidade, aceitabilidade, situacionalidade). Progressão temática. Sequências textuais: descritiva, narrativa, argumentativa, injuntiva, dialogal. Tipos de argumento. Funcionalidade e características dos gêneros textuais circulantes nos órgãos oficiais: sentença, lei, decreto, termo, ata, atestado, certidão, portaria, ofício, memorando, e-mail, aviso etc. Emprego e uso dos pronomes. Pontuação. Características dos diferentes discursos (jornalístico, político, acadêmico, publicitário, literário, científico, etc.). Organização da frase: Processos de coordenação e de subordinação. Verbos que constituem predicado e verbos que não constituem predicado. Tempos e modos verbais. Concordância verbal e nominal. Regência dos nomes e dos verbos. Constituição e funcionalidade do Sujeito. Reescritura de frases: substituição, deslocamento, paralelismo, adequação ao gênero. Morfologia: Classes de palavras, formação das palavras, composição, derivação. Ortografia oficial. Acentuação gráfica. Variação linguística: estilística, sociocultural, geográfica, histórica. Variação entre modalidades da língua (fala e escrita). Norma coloquial, norma culta.'),
  ('tj-go-analista-judiciario', 'Língua Portuguesa', 'Leitura e análise de textos de diferentes gêneros textuais. Linguagem verbal e não-verbal. Mecanismos de produção de sentidos nos textos: polissemia, ironia, comparação, ambiguidade, citação, inferência, pressuposto. Significados contextuais das expressões linguísticas. Organização do texto: Fatores de textualidade (coesão, coerência, intertextualidade, informatividade, intencionalidade, aceitabilidade, situacionalidade). Progressão temática. Sequências textuais: descritiva, narrativa, argumentativa, injuntiva, dialogal. Tipos de argumento. Funcionalidade e características dos gêneros textuais circulantes nos órgãos oficiais: sentença, lei, decreto, termo, ata, atestado, certidão, portaria, ofício, memorando, e-mail, aviso etc. Emprego e uso dos pronomes. Pontuação. Características dos diferentes discursos (jornalístico, político, acadêmico, publicitário, literário, científico, etc.). Organização da frase: Processos de coordenação e de subordinação. Verbos que constituem predicado e verbos que não constituem predicado. Tempos e modos verbais. Concordância verbal e nominal. Regência dos nomes e dos verbos. Constituição e funcionalidade do Sujeito. Reescritura de frases: substituição, deslocamento, paralelismo, adequação ao gênero. Morfologia: Classes de palavras, formação das palavras, composição, derivação. Ortografia oficial. Acentuação gráfica. Variação linguística: estilística, sociocultural, geográfica, histórica. Variação entre modalidades da língua (fala e escrita). Norma coloquial, norma culta.'),
  ('tj-go-analista-apoio-administrativo', 'Conhecimentos Regionais', 'Aspectos da História Social de Goiás: o povoamento branco, os grupos indígenas, a escravidão e cultura negra, os movimentos sociais no campo e a cultura popular. Aspectos da história econômica de Goiás: a mineração no século XVIII, a agropecuária nos séculos XIX e XX, a estrada de ferro e a modernização da economia goiana, as transformações econômicas com a construção de Goiânia e Brasília, industrialização, infraestrutura e planejamento; modernização da agricultura e urbanização do território goiano. Aspectos da história política de Goiás: a independência em Goiás, o Coronelismo na República Velha, as oligarquias, a Revolução de 1930, a administração política de 1930 até os dias atuais. Aspectos históricos e urbanísticos de Goiás e de Goiânia. Aspectos da Cultura Goiana: a culinária regional, as festas religiosas, o folclore goiano, o patrimônio histórico-cultural e o turismo. População goiana: povoamento, movimentos migratórios, densidade e distribuição demográfica, população economicamente ativa. As regiões goianas e as desigualdades regionais. Aspectos físicos do território goiano: hidrografia, clima, relevo e vegetação. Atualidades econômicas, políticas e sociais do Estado de Goiás.'),
  ('tj-go-analista-judiciario', 'Conhecimentos Regionais', 'Aspectos da História Social de Goiás: o povoamento branco, os grupos indígenas, a escravidão e cultura negra, os movimentos sociais no campo e a cultura popular. Aspectos da história econômica de Goiás: a mineração no século XVIII, a agropecuária nos séculos XIX e XX, a estrada de ferro e a modernização da economia goiana, as transformações econômicas com a construção de Goiânia e Brasília, industrialização, infraestrutura e planejamento; modernização da agricultura e urbanização do território goiano. Aspectos da história política de Goiás: a independência em Goiás, o Coronelismo na República Velha, as oligarquias, a Revolução de 1930, a administração política de 1930 até os dias atuais. Aspectos históricos e urbanísticos de Goiás e de Goiânia. Aspectos da Cultura Goiana: a culinária regional, as festas religiosas, o folclore goiano, o patrimônio histórico-cultural e o turismo. População goiana: povoamento, movimentos migratórios, densidade e distribuição demográfica, população economicamente ativa. As regiões goianas e as desigualdades regionais. Aspectos físicos do território goiano: hidrografia, clima, relevo e vegetação. Atualidades econômicas, políticas e sociais do Estado de Goiás.'),
  ('tj-go-analista-apoio-administrativo', 'Legislação Complementar (TJ-GO)', 'Regimento Interno do Tribunal de Justiça do Estado de Goiás. Lei Estadual nº 9.129 de 22 de dezembro de 1981 (com atualizações da Lei nº 20.816/2020). Resolução 325 de 29 de junho de 2020 do Conselho Nacional de Justiça (CNJ). Constituição do Estado de Goiás. Código de Organização Judiciária de Goiás.'),
  ('tj-go-analista-judiciario', 'Legislação Complementar (TJ-GO)', 'Regimento Interno do Tribunal de Justiça do Estado de Goiás. Lei Estadual nº 9.129 de 22 de dezembro de 1981 (com atualizações da Lei nº 20.816/2020). Resolução 325 de 29 de junho de 2020 do Conselho Nacional de Justiça (CNJ). Constituição do Estado de Goiás. Código de Organização Judiciária de Goiás.'),
  ('tj-go-analista-apoio-administrativo', 'Direito Constitucional', 'Direitos e deveres fundamentais. Direitos e deveres individuais e coletivos, direito à vida, à liberdade, à igualdade, à segurança e à propriedade. Direitos sociais. Direitos Difusos. Nacionalidade e cidadania. Direitos políticos. Garantias constitucionais individuais, sociais e políticas. Princípios constitucionais: individuais e da administração pública. Poder constituinte. Normas constitucionais relativas à Administração Pública e aos servidores públicos da Administração Pública. Constituição Federal. Constituição do Estado de Goiás. Princípios e garantias dos membros do poder judiciário. Poder Judiciário: juízes, Tribunais Estaduais e Regionais, do Supremo Tribunal Federal, do Superior Tribunal de Justiça, dos Tribunais e Juízes dos Estados.'),
  ('tj-go-analista-apoio-administrativo', 'Direito Administrativo', 'Princípios de Direito Administrativo. Regime Jurídico-Administrativo. Da Administração Pública: direta e indireta. Atos Administrativos: elementos e atributos. Classificações e espécies dos atos administrativos. Anulação, revogação e convalidação dos atos administrativos Competência. Contratos administrativos: formalização e espécies. Licitação. Lei n.º 8.666/93. Lei n.º 14.133, de 01 de abril de 2021. Recursos administrativos: critérios e prazos. Processos administrativos. Prescrição administrativa. Agentes públicos: agentes políticos e servidores públicos. Controle da Administração Pública. Organizações sociais.'),
  ('tj-go-analista-apoio-administrativo', 'Administração Pública', 'Paradigmas da Administração Pública e reformas administrativas. Administração pública burocrática. Burocracia e disfunções burocráticas. Nova gestão pública. Estado do bem-estar social. Princípios e fundamentos da administração pública. O processo das políticas públicas. Ferramentas de planejamento no setor público: planos; programas de governo; processo orçamentário; Plano Plurianual ­ PPA; Lei de Diretrizes Orçamentárias ­ LDO; Lei Orçamentária Anual ­ LOA. Governança: princípios da governança; fundamentos e governança pública. Governabilidade. Accountability. Estado, Governo e Administração Pública. Planejamento estratégico no setor público e indicadores de desempenho. Parcerias público-privadas. Controles na administração pública. Transparência no setor público: lei de acesso à informação (LEI Nº 12.527, de 18 de novembro de 2011) e leis da transparência e responsabilidade fiscal (Lei Complementar 131/2009 e Lei 101/2000). Gestão por processos em organizações públicas. Inovação no setor público. Terceiro setor: organizações sociais e organizações da sociedade civil de interesse público e leis nº 9.637, de 15 de maio de 1998 e nº 9.790, de 23 de março de 1999.'),
  ('tj-go-analista-judiciario', 'Direito Constitucional', 'O constitucionalismo. Evolução histórica do constitucionalismo brasileiro. Direito constitucional. Formação da Constituição. Constituição: fontes; conceito; objeto; classificações; estrutura. Supremacia da Constituição. Aplicabilidade das normas constitucionais. Interpretação das normas constitucionais: especificidades, métodos de interpretação, princípios da interpretação. Vigência e eficácia das normas constitucionais. Poder constituinte. Controle de constitucionalidade. Sistema. Ação direta de inconstitucionalidade. Ação declaratória de constitucionalidade. Arguição de descumprimento de preceito fundamental. Ação direta de inconstitucionalidade por omissão. Efeitos da decisão no controle abstrato. Modulação dos efeitos da declaração de inconstitucionalidade. A fiscalização abstrata no plano estadual. Controle de constitucionalidade das leis municipais. A ação direta de inconstitucionalidade no âmbito estadual e o problema da norma repetida. Norma constitucional inconstitucional. O fenômeno da recepção da legislação em vigor pela nova Ordem Constitucional. Mutação constitucional. Jurisdição constitucional e processo constitucional. Coisa julgada e processo constitucional. A Fiscalização incidental. Administração pública e o controle de constitucionalidade. Lei federal nº 9.868, de 10 de novembro de 1.999. Lei federal nº 9.882, de 03 de dezembro de 1.999. 3. Princípios fundamentais da Constituição Federal. Direitos e garantias fundamentais: conceito, evolução, características, titularidade, destinatários e limites. Dos direitos e deveres individuais e coletivos. Tratados e convenções sobre direitos humanos: formação, extinção e efeitos jurídicos; hierarquia, incorporação e efeito dos tratados internacionais de proteção dos direitos humanos no direito brasileiro. Direitos sociais. Direitos políticos. Partidos políticos. Direitos de nacionalidade. Tutela constitucional dos direitos e das liberdades. Mandado de segurança, individual e coletivo. Mandado de Injunção. Habeas corpus. Habeas data. Ação popular. Ação civil pública. Da Defesa do Estado e das Instituições Democráticas. Organização do Estado Brasileiro: Estado Federal: conceito, formação, evolução e características. Federação brasileira: origem, formação, componentes, repartição de competências e intervenção nos Estados e nos Municípios. Organização político-administrativa: União; Estados federados; Municípios; Distrito Federal; Territórios; regiões metropolitanas, aglomerações urbanas e microrregiões. Bens públicos. Administração pública: Disposições gerais; Servidores públicos e militares. Organização dos Poderes na Constituição Federal. Poder Executivo. Presidente e Vice-Presidente da República: Atribuições e Responsabilidades. Ministros de Estado. Poder Legislativo. Órgãos, funcionamento e competências. Prerrogativas e impedimentos no exercício do mandato parlamentar. Processo legislativo. Fiscalização contábil, financeira e orçamentária. Tribunal de Contas da União. Poder Judiciário: disposições gerais, funções, organização, competências e funcionamento; direitos e deveres da Magistratura; garantias da magistratura; precatórios; Conselho Nacional de Justiça.'),
  ('tj-go-analista-judiciario', 'Direito Administrativo', 'As funções do Estado. O regime jurídico-administrativo. Conceito de Direito Administrativo. Estado, governo e Administração. Conceito de Administração Pública. Poderes da Administração Pública. Conceitos jurídicos de função e de poder. Função administrativa estatal. Separação dos poderes e função administrativa. Tipos de função administrativa estatal. Poderes da Administração: poder regulamentar e poder normativo, poder hierárquico, poder disciplinar, poder discricionário, poder vinculado e poder de polícia. Princípios Constitucionais do Direito Administrativo. Ato administrativo. Controle de mérito e de legalidade dos atos administrativos. Controle sistemático dos atos administrativos. Servidores Públicos. Agentes Públicos. Remuneração dos servidores e de agentes públicos. Regime dos servidores públicos e titulares de cargos públicos na Constituição Federal e na Constituição do Estado do Goiás. Cargo, emprego e função pública. Provimento. Nomeação. Concurso Público. Posse e exercício. Afastamentos. Estabilidade. Transferência. Readaptação. Reversão. Reintegração. Recondução. Disponibilidade. Aproveitamento. Promoção. Vacância. Movimentações. Lei nº 20.756, de 28 de janeiro de 2020 (Estatuto dos Servidores do Estado de Goiás). Direitos e vantagens dos servidores públicos. Sistema Remuneratório. Licenças. Afastamentos. Deveres e responsabilidades dos servidores públicos. Regime disciplinar. Disposições Constitucionais (Constituição Federal e Constituição Estadual) aplicáveis aos servidores públicos. Controles da Administração Pública: Controle administrativo; Controle legislativo ou político; Controle judicial. Discricionariedade administrativa e controle judicial. Controle interno e controle externo. Controle pelo Tribunal de Contas. Controle sistemático das delegações de serviços públicos. Improbidade administrativa: Lei Federal nº 8.429, de 02 de junho de 1992. Lei de Responsabilidade Fiscal (Lei Complementar nº 101, de 04 de maio de 2000). Lei de Acesso à Informação (Lei Federal nº 12.527, de 18 de novembro de 2011). Lei Estadual de Responsabilização Administrativa e Anticorrupção Empresarial (Lei nº 18.672, de 13 de novembro de 2014 e suas regulamentações). Lei que regula o Processo administrativo no âmbito da Administração Pública do Estado de Goiás. Lei que impõe a obrigação da implantação do programa de integridade (compliance) às empresas que contratam com a Administração Pública do Estado de Goiás (Lei nº 20.489, de 10 de junho de 2019). Bens públicos. Espécies de bens públicos. Instrumentos negociais relacionados à gestão e utilização dos bens públicos. Uso do bem público. Estatuto da Cidade (Lei Federal nº 10.257, de 10 de julho de 2001). Licitação: Fases da licitação. Contratação direta. Alienações. Instrumentos auxiliares. Recursos administrativos. Crimes. Licitação e mandado de segurança. Registro de preços. (Lei nº 8.666/93 e Lei nº 14.133, de 01 de abril de 2021). Contrato administrativo. Espécies. Conceito. Características. Nulidades dos contratos. Obrigações do Estado derivadas de contratos inválidos ou inexistentes. Hipóteses de extinção. Recebimento do objeto do contrato. (Lei nº 8.666/93 e Lei nº 14.133, de 01 de abril de 2021). Serviço público. Regime jurídico da concessão, da permissão e da autorização de serviço público. Formas de extinção da concessão e seus efeitos jurídicos. Intervenção, encampação e caducidade. Reversão dos bens. Responsabilidade do concessionário e do Poder concedente. Permissão. Concessão comum. Concessão em parcerias público-privadas patrocinadas e administrativas. Concessões em regime especial. Concessão de obra pública. Concessão de uso de bem público. Parcerias com o terceiro setor. Convênios e outras espécies de ajustes colaborativos. Organizações sociais. Organização da sociedade civil de interesse público (OSCIP). Organizações da Sociedade Civil (OSC). Lei nº 9.637, de 15 de maio de 1998. Lei nº 9.790, de 23 de março de 1999. Lei nº 13.019, de 31 de julho de 2014. Desapropriação. Conceito. Competências relacionadas à desapropriação. Espécies de desapropriação. Ocupação provisória. Limitação administrativa. Loteamento e zoneamento. Estatuto da Cidade. Atos administrativos, atos legislativos e atos judiciais. Responsabilidades dos contratados e delegatários de serviços públicos. Procedimento administrativo e judicial. Direito de regresso. Organização administrativa. Súmulas e jurisprudência do Tribunal de Justiça e dos Tribunais Superiores (STJ e STF) em matéria da administração pública e em matéria relacionada ao Direito Administrativo. Dispositivos da Constituição do Estado de Goiás aplicáveis ao Direito Administrativo.'),
  ('tj-go-analista-judiciario', 'Direito Civil', 'Lei de Introdução às Normas do Direito Brasileiro; Das pessoas. Desconsideração da Personalidade Jurídica. Do domicílio. Direitos da Personalidade. Dos bens. Do bem de família. Dos fatos jurídicos. Do negócio jurídico. Dos defeitos dos negócios jurídicos. Das nulidades. Dos atos jurídicos lícitos e lícitos. Da prescrição e da decadência. Da prova. Do direito das obrigações. Das modalidades das obrigações. Do adimplemento e extinção das obrigações. Mora, cláusula penal, perdas e danos. Dos contratos em geral. Do enriquecimento ilícito. Da resolução por onerosidade excessiva. Exceção do contrato não cumprido. Formação e extinção. Vícios redibitórios e evicção. Das várias espécies de contrato. Dos atos unilaterais. Dos títulos de crédito. Da responsabilidade civil em geral. Responsabilidade subjetiva e objetiva. Do direito das coisas e direitos reais. Da posse. Usucapião. Dos direitos reais. Multipropriedade (Lei n.º 13.777, de 20 de dezembro de 2018). Do condomínio. Da superfície. Das servidões. Do usufruto. Da habitação. Alienação fiduciária. Do direito de família. Casamento. Regime de bens. Da união estável. Da tutela e da curatela. Adoção. Poder familiar. Alimentos. Do direito das sucessões. Da sucessão em geral. Da sucessão legítima. Da sucessão testamentária. Do inventário e da partilha. Registros públicos. (Lei nº 6.015, de 31 de dezembro de 1973). Da alienação fiduciária (Decreto-Lei nº 911, de 1º de outubro de 1969). Da locação de imóveis urbanos (Lei nº 8.245, de 18 de outubro de 1991). Estatuto da Pessoa com Deficiência (Lei nº 13.146, de 06 de julho de 2015). Súmulas vinculantes e não vinculantes em matéria Civil ­ STJ e STF. Parcelamento do Solo Urbano (Lei nº 6.766, de 19 de dezembro de 1979, com as alterações da Lei nº 14.118, de 13 de janeiro de 2021).'),
  ('tj-go-analista-judiciario', 'Direito Processual Civil', 'Teoria Geral do Direito Processual Civil. Normas processuais civis. Fontes do Direito Processual Civil. Aplicação e interpretação da lei processual civil. Da norma processual no tempo e no espaço. Organização Judiciária. Meios alternativos de solução de conflitos. Da jurisdição. Da ação. Condições da Ação. Classificação das Ações. Das Normas Fundamentais e da Aplicação das Normas Processuais. Competência. Competência absoluta e relativa. Das causas de modificações da competência. Casos de prorrogação legal da competência. Conflito de competência. Processo. Conceito. Classificação. Natureza Jurídica. Princípios informativos do processo civil. Princípios constitucionais do processo civil. As garantias constitucionais do processo civil. A relação processual. Características da relação processual. Sujeitos da relação jurídica: Sujeitos principais. Sujeitos secundários. Sujeitos Especiais. Pressupostos processuais. Das partes e dos procuradores. Da capacidade processual. Legitimação ordinária. Legitimação extraordinária. A substituição processual. Dos deveres das partes e dos procuradores. Do litisconsórcio. Da assistência. Da intervenção de terceiros. Da oposição. Da denunciação da lide. Chamamento ao processo. Incidente de Desconsideração da Personalidade jurídica. Amicus Curiae. Da tutela provisória. Disposições Gerais. Da tutela de urgência. Da tutela da evidência. Dos atos processuais. Definição. Características dos atos processuais. Princípios dos atos processuais. Classificação dos atos processuais. Atos do juiz. Atos das partes. Atos dos auxiliares das partes. Atos processuais simples e complexos. Das comunicações dos atos processuais. Das cartas. Das citações. Das intimações. Das nulidades. De outros atos processuais. Da distribuição e do registro. Do valor da causa. Dos prazos. Conceito. Classificação. Princípios. Contagem. Preclusão. Formação, suspensão e extinção do processo. Do Processo de Conhecimento. Petição inicial: conceito, requisitos. Do pedido: espécies, modificação, cumulação. Causa de pedir. Dos documentos necessários à propositura da ação. Despacho inicial: objeto, natureza. Do julgamento liminar de improcedência das ações repetitivas. Do recurso cabível e seu procedimento. Emenda da inicial. Do indeferimento liminar da petição inicial. Do recurso cabível e seu procedimento. Da antecipação dos efeitos da tutela de mérito. Requisitos. Da fungibilidade entre a tutela antecipada e as medidas cautelares. Da citação. Dos efeitos da citação. Da resposta do réu: contestação, exceções (incompetência, impedimento e suspeição), reconvenção. Da revelia. Dos efeitos da revelia. Das alegações do réu. Do julgamento conforme o estado do processo. Da extinção do processo sem resolução do mérito. Do julgamento antecipado da lide. Da resolução do mérito. Da audiência preliminar. Das provas: conceito, modalidades, princípios gerais, objeto, ônus, procedimentos. Da audiência de instrução e julgamento. Da sentença. Requisitos e efeitos da sentença. Classificação da sentença. Publicação. Intimação das partes e dos procuradores. Sentença em audiência e início do prazo recursal. Condenação do devedor na emissão de declaração de vontade. Coisa julgada. Conceito. Limites objetivos e subjetivos. Coisa julgada formal e coisa julgada material. Princípio do deduzido e do dedutível. Reexame da sentença. Liquidação da sentença. Cumprimento da sentença. Procedimento. Títulos executivos judiciais. Impugnação. Execução provisória. Competência para o cumprimento da sentença. Cumprimento da sentença condenatória na indenização por ato ilícito. Ação rescisória. Recursos. Conceito, fundamentos, princípios, classificação, pressupostos intrínsecos e extrínsecos de admissibilidade, efeitos, juízo de mérito. Apelação. Agravos. Embargos infringentes. Embargos de divergência. Embargos de declaração. Recurso de terceiro prejudicado. Recurso pelo Ministério Público. Recurso adesivo. Recurso extraordinário. Requisitos. Repercussão Geral. Recurso Especial. Recursos especiais repetitivos. Processo de execução. Princípios. Das partes. Da competência. Dos requisitos necessários para realizar qualquer execução. Do inadimplemento do devedor. Espécies de execução. Da penhora, avaliação e expropriação. Da citação do devedor e da indicação de bens. Da penhora e do depósito. Da avaliação. Da adjudicação. Da alienação por iniciativa particular. Da alienação em hasta pública. Do Pagamento ao credor. Da Execução contra a Fazenda Pública. Da execução da prestação alimentícia. Dos embargos à execução. Prazos para embargos. Natureza jurídica. Legitimidade e procedimento. Dos embargos à execução contra a Fazenda Pública. Dos embargos na execução por carta. Da execução por quantia certa contra devedor insolvente. Da suspensão e extinção do processo. Dos procedimentos especiais. Dos Procedimentos especiais de jurisdição contenciosa. Dos procedimentos especiais de jurisdição voluntária. Juizados especiais cíveis (Lei nº 9.099, de 26 de setembro de 1995). Súmulas vinculantes e não vinculantes em matéria processual civil ­ STJ e STF.'),
  ('tj-go-analista-judiciario', 'Direito Penal', 'Princípios constitucionais penais. Aplicação da lei penal. Crime. Conceito. Elementos. Tipicidade. Relação de causalidade. Consumação, tentativa, crime impossível, desistência voluntária e arrependimento eficaz. Arrependimento posterior. Dolo e culpa. Culpabilidade. Erro sobre elementos do tipo, erro determinado por terceiro, erro sobre a pessoa e erro sobre a ilicitude do fato. Coação irresistível e obediência hierárquica. Ilicitude. Causas de exclusão. Imputabilidade penal. Concurso de pessoas. Penas privativas de liberdade. Penas restritivas de direitos. 17. Pena de multa. Cominação das penas. Aplicação das penas. Concurso de crimes. Conflito aparente de normas. Erro na execução. Limite das penas. Suspensão condicional da pena. Livramento condicional. Efeitos da condenação. Reabilitação. Medidas de segurança. Ação Penal. Extinção da punibilidade. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a propriedade intelectual. Crimes contra a dignidade sexual. Crimes contra a Administração pública. Abuso de autoridade (Lei nº 13.869, de 05 de setembro de 2019). Execução Penal (Lei nº 7.210, de 11 de julho de 1984). Preconceito Racial (Lei nº 7.716, de 05 de janeiro de 1989). Crimes praticados contra a criança e o adolescente (Lei nº 8.069, de 13 de julho de 1990). Crimes hediondos (Lei nº 8.072, de 25 de julho de 1990). Crimes em licitações e contratos administrativos (Lei nº 14.133, de 01 de abril de 2021). Crimes de tortura (Lei nº 9.455, de 07 de abril de 1997). Crimes lavagem ou ocultação de bens, direitos e valores (Lei nº 9.613, de 03 de março de 1998). Crimes contra idosos (Lei nº 10.741, de 1º de outubro de 2003). Crimes previstos no estatuto do desarmamento (Lei nº 10.826, de 22 de dezembro de 2003). Violência doméstica (Lei nº 11.340, de 07 de agosto de 2006). Lei antidrogas (Lei nº 11.343, de 23 de agosto de 2006). Organizações criminosas (Lei nº 12.850, de 02 de agosto de 2013). Lei "Anticrime" (Lei nº 13.964, de 24 de dezembro de 2019).'),
  ('tj-go-analista-judiciario', 'Direito Processual Penal', 'Princípios gerais e constitucionais do processo penal. Aplicação da lei processual no tempo, no espaço e em relação às pessoas. Fontes e Interpretação da Lei processual penal. Persecução penal. Inquérito policial, Termo circunstanciado de ocorrência. Comissão parlamentar de inquérito. Investigação criminal promovida pelo Ministério Público. Outras formas de investigação. Arquivamento de inquérito. Denúncia. Sujeitos do processo: do juiz, do Ministério Público, do acusado e defensor, dos assistentes e auxiliares da Justiça. Impedimentos e suspeições. Atos processuais: comunicações, citações, intimações e notificações. Decisões interlocutórias. Audiência de custódia. Audiência de instrução. Sentença: tipos, estrutura, efeitos. Fixação da pena. Jurisdição e competência. Critérios de determinação e modificação de competência. Perpetuatio Jurisdictionis. Incompetência. Conexão e continência. Das questões e processos incidentes. Medidas assecuratórias: sequestro, hipoteca legal e arresto. Incidentes de falsidade e de insanidade mental do acusado. Restituição das coisas apreendidas. Perdimento de bens. Alienação antecipada de bens. Da prova: conceito, princípios, finalidade, objeto, meios, espécies, ônus, procedimento probatório, limitações constitucionais das provas, sistemas de apreciação. Interceptação de comunicações telefônicas e do fluxo de comunicações em sistemas de informática e telemática. Quebra do sigilo fiscal, bancário e de dados. Da prisão em flagrante. Prisão temporária. Prisão preventiva. Prisão domiciliar. Medidas cautelares diversas da prisão. Liberdade provisória. Fiança. Ação penal. Processo e procedimento. Pressupostos processuais. Formas procedimentais. Procedimento comum ordinário. Procedimento comum sumário. Procedimentos Especiais: do Tribunal do Júri, nos crimes de abuso de autoridade, nos crimes de responsabilidade dos funcionários públicos, nos crimes contra a honra, nos crimes contra a propriedade imaterial, nas restaurações de autos extraviados ou destruídos. Das nulidades. Dos recursos. Recursos especial e extraordinário. Coisa julgada. Revisão criminal. Habeas corpus. Mandado de segurança. Execução Penal. Competência. Execução das penas privativas de liberdade, restritivas de direito e das medidas de segurança. Regimes de cumprimento da pena. Juizado especial criminal (Lei nº 9.099, de 26 de setembro de 1995). Interceptação telefônica (Lei nº 9.296, 24 de julho de 1996). Lavagem ou ocultação de bens, direitos e valores (Lei nº 9.613, de 03 de março de 1998). Proteção a testemunhas (Lei nº 9.807, de13 de julho de 1999). Organizações criminosas (Lei nº 12.850, de 02 de agosto de 2013). Violência doméstica (Lei nº 11.340, de 07 de agosto de 2006). Drogas (Lei nº 11.343, de 23 de agosto de 2006). Lei Anticrime (Lei nº 13.964, de 24 de dezembro de 2019).')
) as v(slug, materia, texto)
join public.editais_catalog e on e.slug = v.slug
join public.subjects_catalog s on s.name = v.materia
on conflict (edital_catalog_id, subject_catalog_id) do update
  set texto = excluded.texto, fonte_url = excluded.fonte_url, conferido_em = excluded.conferido_em;

do $$
declare v int;
begin
  select count(*) into v from public.edital_programas ep
  join public.editais_catalog e on e.id = ep.edital_catalog_id
  where e.slug in ('tj-go-analista-apoio-administrativo','tj-go-analista-judiciario');
  if v <> 15 then raise exception 'esperado 15 linhas de programa (6+9), achei %', v; end if;
end $$;
